/* Diagnostic-only native function profiler (GANGSTAR_NATIVE_PROFILER).
 *
 * Hooks the generated set of engine functions (gangstar_native_profile_sites.h,
 * produced at build time into work/generated by tools/generate_native_profile_sites.py)
 * with a thunk that times calls on the game's main thread only. Arguments,
 * the stack and the callee's frame are left untouched: the caller's return
 * address is kept on a private shadow stack and the callee returns through
 * an exit stub. Only frames over 50 ms are reported, with the functions that
 * spent the most self time (time not spent in other hooked functions).
 * Cheap, very frequent functions disable themselves to bound overhead.
 */
#ifdef GANGSTAR_NATIVE_PROFILER
#include "gangstar_native_profile.h"
#ifndef RIO_PROF_SITES_HEADER
#define RIO_PROF_SITES_HEADER "gangstar_native_profile_sites.h"
#endif
#include RIO_PROF_SITES_HEADER
#include "gangstar_wait_perf.h"
#include "utils/logger.h"
#include <so_util/so_util.h>
#include <kubridge.h>
#include <psp2/kernel/processmgr.h>
#include <psp2/kernel/clib.h>
#include <string.h>
extern so_module so_mod;

__asm__(
    ".text\n.arm\n.align 2\n"
    ".global rio_prof_entry\n.type rio_prof_entry,%function\n"
    "rio_prof_entry:\n"
    "  push {r0-r3, r12, lr}\n"      /* r12 = site index (from the per-site stub) */
    "  mov r0, r12\n"
    "  ldr r1, [sp, #20]\n"          /* caller's return address */
    "  bl rio_prof_enter\n"          /* r0 = original code, r1 = timed? */
    "  str r0, [sp, #16]\n"
    "  cmp r1, #0\n"
    "  pop {r0-r3, r12, lr}\n"       /* pop keeps the flags */
    "  bxeq r12\n"                   /* untimed: plain tail call */
    "  adr lr, rio_prof_exit_stub\n"
    "  bx r12\n"
    ".global rio_prof_exit_stub\n.type rio_prof_exit_stub,%function\n"
    "rio_prof_exit_stub:\n"
    "  push {r0-r3}\n"               /* return value (softfp: r0/r1) */
    "  bl rio_prof_leave\n"          /* r0 = caller's return address */
    "  mov r12, r0\n"
    "  pop {r0-r3}\n"
    "  bx r12\n");
extern void rio_prof_entry(void);

#define RIO_PROF_DEPTH 256
#define RIO_PROF_FRAME_CALLS 2000
#define RIO_PROF_REPORT_US 50000
#define RIO_PROF_TOP 12
static uintptr_t targets[RIO_PROF_SITES];
static uint8_t disabled[RIO_PROF_SITES];
static struct { uint64_t incl; uint32_t calls; } life[RIO_PROF_SITES];
static struct { uint64_t self, incl; uint32_t calls; } frame[RIO_PROF_SITES];
static uint16_t touched[RIO_PROF_SITES];
static unsigned touched_count, installed, disabled_count;
static struct { uint32_t index; uintptr_t lr; uint64_t start, child; } stack[RIO_PROF_DEPTH];
static unsigned depth;
static int ready;
static uint64_t fs_main_wait_us; static unsigned fs_main_waits;

uint64_t rio_prof_enter(uint32_t index, uintptr_t lr) {
    uintptr_t target = targets[index];
    if (!ready || disabled[index] || depth >= RIO_PROF_DEPTH ||
        frame[index].calls >= RIO_PROF_FRAME_CALLS || !gangstar_wait_is_main())
        return target;
    if (!frame[index].calls && !frame[index].incl) touched[touched_count++] = (uint16_t)index;
    ++frame[index].calls;
    stack[depth].index = index; stack[depth].lr = lr; stack[depth].child = 0;
    stack[depth++].start = sceKernelGetProcessTimeWide();
    return (uint64_t)target | ((uint64_t)1 << 32);
}
uintptr_t rio_prof_leave(void) {
    uint64_t now = sceKernelGetProcessTimeWide();
    --depth;
    uint64_t incl = now - stack[depth].start;
    uint64_t self = incl > stack[depth].child ? incl - stack[depth].child : 0;
    uint32_t index = stack[depth].index;
    frame[index].incl += incl; frame[index].self += self;
    if (depth) stack[depth - 1].child += incl;
    return stack[depth].lr;
}

void gangstar_native_profile_frame(unsigned frame_number, uint64_t frame_us) {
    if (!ready) return;
    if (frame_us >= RIO_PROF_REPORT_US && touched_count) {
        unsigned top[RIO_PROF_TOP], used = 0;
        uint64_t timed = 0;
        for (unsigned t = 0; t < touched_count; ++t) {
            unsigned i = touched[t]; timed += frame[i].self;
            unsigned pos = used < RIO_PROF_TOP ? used++ : RIO_PROF_TOP;
            if (pos == RIO_PROF_TOP && frame[i].self <= frame[top[RIO_PROF_TOP - 1]].self) continue;
            if (pos == RIO_PROF_TOP) pos = RIO_PROF_TOP - 1;
            while (pos && frame[top[pos - 1]].self < frame[i].self) { top[pos] = top[pos - 1]; --pos; }
            top[pos] = i;
        }
        l_info("RIO_PROF frame=%u total_us=%llu timed_self_us=%llu functions=%u",
            frame_number, (unsigned long long)frame_us, (unsigned long long)timed, touched_count);
        for (unsigned k = 0; k < used; ++k) {
            unsigned i = top[k];
            l_info("RIO_PROF_FN frame=%u fn=0x%x self_us=%llu incl_us=%llu calls=%u",
                frame_number, (unsigned)rio_prof_sites[i].offset, (unsigned long long)frame[i].self,
                (unsigned long long)frame[i].incl, frame[i].calls);
        }
    }
    for (unsigned t = 0; t < touched_count; ++t) {
        unsigned i = touched[t];
        life[i].incl += frame[i].incl; life[i].calls += frame[i].calls;
        // Very frequent, cheap functions only add overhead: stop timing them.
        if (!disabled[i] && life[i].calls >= 3000 && life[i].incl / life[i].calls < 40) {
            disabled[i] = 1; ++disabled_count;
        }
        frame[i].self = frame[i].incl = 0; frame[i].calls = 0;
    }
    touched_count = 0;
    static unsigned reports;
    if (!(++reports % 600))
    {
        l_info("RIO_PROF_STATUS installed=%u disabled_hot=%u depth=%u", installed, disabled_count, depth);
        l_info("RIO_FSLOCK_MAIN waits=%u wait_us=%llu", fs_main_waits, (unsigned long long)fs_main_wait_us);
        fs_main_waits = 0; fs_main_wait_us = 0;
    }
}


/* ---- Engine file-system lock trace --------------------------------------
 * CCustomFileSystem/CGlfFileSystem guard every file open with one global
 * glf::ReadWriteMutexLock and hold it for the whole open. When another thread
 * holds it, the frame thread waits. Log who holds it, for how long, from
 * which engine function and for which file, and how long each waiter waited.
 */
#include <psp2/kernel/threadmgr.h>
#include <stdio.h>
#define RIO_FS_LOCK_OFFSET 0x103190c
#define RIO_FS_SLOTS 24
#define RIO_FS_LOG_LIMIT 600
#define RIO_FS_SLOW_HOLD_US 8000
#define RIO_FS_SLOW_WAIT_US 3000
typedef int (*RioLockFn)(void *, unsigned);
typedef void (*RioUnlockFn)(void *);
static RioLockFn fs_orig_wlock, fs_orig_rlock;
static RioUnlockFn fs_orig_wunlock, fs_orig_runlock;
static void *fs_lock;
static struct FsSlot {
    SceUID tid; unsigned depth; uint64_t acquired; uint32_t wait_us; uintptr_t caller;
    char path[80];
} fs_slots[RIO_FS_SLOTS];
static unsigned fs_logged;

static struct FsSlot *fs_slot(void) {
    SceUID tid = sceKernelGetThreadId();
    for (unsigned i = 0; i < RIO_FS_SLOTS; ++i) if (fs_slots[i].tid == tid) return &fs_slots[i];
    for (unsigned i = 0; i < RIO_FS_SLOTS; ++i)
        if (__sync_bool_compare_and_swap(&fs_slots[i].tid, 0, tid)) return &fs_slots[i];
    return NULL;
}
static void fs_note_acquired(struct FsSlot *slot, uint64_t start, uintptr_t caller) {
    uint64_t now = sceKernelGetProcessTimeWide();
    if (!slot || slot->depth++) return;
    slot->acquired = now; slot->wait_us = (uint32_t)(now - start); slot->caller = caller;
    if (gangstar_wait_is_main() && slot->wait_us >= 1000) { fs_main_wait_us += slot->wait_us; ++fs_main_waits; }
}
struct FsEvent { SceUID tid; uint32_t wait_us, hold_us; uintptr_t caller; int main; char kind; char path[80]; };
// Returns 1 when a slow hold/wait should be logged (after the real unlock).
static int fs_note_released(struct FsSlot *slot, char kind, struct FsEvent *event) {
    if (!slot || !slot->depth || --slot->depth) return 0;
    uint32_t hold = (uint32_t)(sceKernelGetProcessTimeWide() - slot->acquired);
    int slow = (hold >= RIO_FS_SLOW_HOLD_US || slot->wait_us >= RIO_FS_SLOW_WAIT_US) && fs_logged < RIO_FS_LOG_LIMIT;
    if (slow) {
        ++fs_logged;
        event->tid = slot->tid; event->wait_us = slot->wait_us; event->hold_us = hold;
        event->caller = slot->caller; event->main = gangstar_wait_is_main(); event->kind = kind;
        memcpy(event->path, slot->path, sizeof(event->path));
    }
    slot->path[0] = 0;
    return slow;
}
static void fs_log(const struct FsEvent *e) {
    SceKernelThreadInfo info; memset(&info, 0, sizeof(info)); info.size = sizeof(info);
    const char *name = sceKernelGetThreadInfo(e->tid, &info) >= 0 ? info.name : "?";
    l_info("RIO_FSLOCK kind=%c main=%d thread=%s wait_us=%u hold_us=%u caller=0x%x path=%s",
        e->kind, e->main, name, (unsigned)e->wait_us, (unsigned)e->hold_us,
        (unsigned)(e->caller - so_mod.load_addr), e->path[0] ? e->path : "-");
}
static int fs_wlock(void *self, unsigned timeout) {
    if (self != fs_lock) return fs_orig_wlock(self, timeout);
    uintptr_t caller = (uintptr_t)__builtin_return_address(0);
    uint64_t start = sceKernelGetProcessTimeWide();
    int result = fs_orig_wlock(self, timeout);
    fs_note_acquired(fs_slot(), start, caller);
    return result;
}
static int fs_rlock(void *self, unsigned timeout) {
    if (self != fs_lock) return fs_orig_rlock(self, timeout);
    uintptr_t caller = (uintptr_t)__builtin_return_address(0);
    uint64_t start = sceKernelGetProcessTimeWide();
    int result = fs_orig_rlock(self, timeout);
    fs_note_acquired(fs_slot(), start, caller);
    return result;
}
static void fs_wunlock(void *self) {
    struct FsEvent event;
    int slow = self == fs_lock && fs_note_released(fs_slot(), 'w', &event);
    fs_orig_wunlock(self);
    if (slow) fs_log(&event);
}
static void fs_runlock(void *self) {
    struct FsEvent event;
    int slow = self == fs_lock && fs_note_released(fs_slot(), 'r', &event);
    fs_orig_runlock(self);
    if (slow) fs_log(&event);
}
// Called by the native-startup probes of CCustomFileSystem/CGlfFileSystem
// ::createAndOpenFile just before the original runs (and takes the lock).
void gangstar_fs_trace_path(const char *path) {
    if (!fs_lock || !path) return;
    struct FsSlot *slot = fs_slot();
    if (slot && !slot->depth) snprintf(slot->path, sizeof(slot->path), "%s", path);
}

// Build a 6-word trampoline (two relocated prologue words + jump back) and
// hook the function. Returns the trampoline, or 0 if the prologue differs.
static uintptr_t rio_hook_relocated(uintptr_t address, uint32_t w0, uint32_t w1, uint32_t *t, uintptr_t replacement, uintptr_t *original) {
    uint32_t current[2]; memcpy(current, (void *)address, 8);
    if (current[0] != w0 || current[1] != w1) return 0;
    for (unsigned n = 0; n < 2; ++n) {
        uint32_t w = current[n];
        if ((w & 0x0f7f0000) == 0x051f0000) {                    // ldr rd,[pc,#+-imm]
            uint32_t imm = w & 0xfff;
            uintptr_t source = address + n * 4 + 8;
            source = (w & (1u << 23)) ? source + imm : source - imm;
            memcpy(&t[4 + n], (void *)source, 4);
            t[n] = (w & 0xff7ff000) | (1u << 23) | 8;
        } else { t[n] = w; t[4 + n] = 0; }
    }
    t[2] = 0xe51ff004; t[3] = address + 8;
    kuKernelFlushCaches(t, 6 * 4);
    *original = (uintptr_t)t;                                 // callable before the hook goes live
    hook_addr(address, replacement);
    kuKernelFlushCaches((void *)address, 8);
    return (uintptr_t)t;
}
static void rio_fs_lock_trace_install(void) {
    static const struct { uint32_t offset, w0, w1; uintptr_t replacement; uintptr_t *original; } sites[] = {
        {0x904298, 0xe92d41f0, 0xe1a04000, (uintptr_t)fs_wlock, (uintptr_t *)&fs_orig_wlock},
        {0x904218, 0xe92d41f0, 0xe1a04000, (uintptr_t)fs_rlock, (uintptr_t *)&fs_orig_rlock},
        {0x904494, 0xe92d4070, 0xe1a04000, (uintptr_t)fs_wunlock, (uintptr_t *)&fs_orig_wunlock},
        {0x904438, 0xe92d4070, 0xe1a04000, (uintptr_t)fs_runlock, (uintptr_t *)&fs_orig_runlock},
    };
    const unsigned count = sizeof(sites) / sizeof(sites[0]);
    if (so_mod.load_addr + 0x904500 > so_mod.text_base + so_mod.text_size) return;   // not this library
    uint32_t *code = so_alloc_exec(count * 6 * 4);
    if (!code) { l_error("RIO_FSLOCK install failed: no executable memory"); return; }
    uintptr_t tramp[4] = {0};
    // All four lock functions must hook, or none: a lock without its unlock would skew depth.
    for (unsigned i = 0; i < 4; ++i) {
        uint32_t current[2]; memcpy(current, (void *)(so_mod.load_addr + sites[i].offset), 8);
        if (current[0] != sites[i].w0 || current[1] != sites[i].w1) {
            l_warn("RIO_FSLOCK not installed: lock prologue 0x%x changed", (unsigned)sites[i].offset); return;
        }
    }
    // Unlock hooks first, so a lock taken after its hook is live always meets a live unlock hook.
    static const unsigned order[] = {2, 3, 0, 1};
    for (unsigned k = 0; k < count; ++k) {
        unsigned i = order[k];
        tramp[i] = rio_hook_relocated(so_mod.load_addr + sites[i].offset, sites[i].w0, sites[i].w1,
            code + i * 6, sites[i].replacement, sites[i].original);
    }
    fs_lock = (void *)(so_mod.load_addr + RIO_FS_LOCK_OFFSET);
    for (unsigned i = 0; i < count; ++i) if (!tramp[i]) { l_error("RIO_FSLOCK partial install %u", i); }
    l_info("RIO_FSLOCK installed lock=%p", fs_lock);
}

void gangstar_native_profile_install(void) {
    rio_fs_lock_trace_install();
    // Per site: 6-word relocated prologue trampoline + 3-word entry stub, in
    // the executable tail of the module block. Install as many as fit.
    unsigned capacity = (unsigned)(so_exec_available() / (9 * 4));
    if (capacity > RIO_PROF_SITES) capacity = RIO_PROF_SITES;
    void *base = capacity ? so_alloc_exec((size_t)capacity * 9 * 4) : NULL;
    if (!base) { l_error("RIO_PROF install failed: no executable memory left"); return; }
    uint32_t *code = base;
    for (unsigned i = 0; i < capacity; ++i) {
        const RioProfSite *s = &rio_prof_sites[i];
        uintptr_t address = so_mod.load_addr + s->offset;
        uint32_t current[2]; memcpy(current, (void *)address, 8);
        if (address < so_mod.text_base || address + 8 > so_mod.text_base + so_mod.text_size ||
            current[0] != s->w0 || current[1] != s->w1) continue;   // already hooked or unexpected
        uint32_t *t = code + i * 9;
        for (unsigned n = 0; n < 2; ++n) {
            uint32_t w = current[n];
            if ((w & 0x0f7f0000) == 0x051f0000) {                    // ldr rd,[pc,#+-imm]
                uint32_t imm = w & 0xfff;
                uintptr_t source = address + n * 4 + 8;
                source = (w & (1u << 23)) ? source + imm : source - imm;
                memcpy(&t[4 + n], (void *)source, 4);
                t[n] = (w & 0xff7ff000) | (1u << 23) | 8;             // ldr rd,[pc,#8] -> t[4+n]
            } else { t[n] = w; t[4 + n] = 0; }
        }
        t[2] = 0xe51ff004; t[3] = address + 8;                       // ldr pc,[pc,#-4]; resume
        t[6] = 0xe3000000 | ((i >> 12) & 15) << 16 | 12u << 12 | (i & 0xfff); // movw r12,#i
        t[7] = 0xe51ff004; t[8] = (uint32_t)(uintptr_t)rio_prof_entry;
        targets[i] = (uintptr_t)t;
        kuKernelFlushCaches(t, 9 * 4);
        hook_addr(address, (uintptr_t)&t[6]);
        kuKernelFlushCaches((void *)address, 8);
        ++installed;
    }
    ready = installed != 0;
    l_info("RIO_PROF installed=%u of %u sites (room for %u) block=%p", installed, (unsigned)RIO_PROF_SITES, capacity, base);
}
#endif
